// db.js - an in-memory Postgres, ready to use. You do NOT edit this file.
//
// It behaves like real PostgreSQL (same SQL, same pool.query, same $1
// parameters) but lives in memory, so there is nothing to install. It is seeded
// with 8 locations and 200 sightings, generated the SAME way every run, so the
// numbers on your dashboard never change between runs.
import { newDb } from 'pg-mem'

const SCHEMA = `
  CREATE TABLE locations (
    id   SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    city TEXT NOT NULL
  );
  CREATE TABLE sightings (
    id          SERIAL PRIMARY KEY,
    location_id INTEGER NOT NULL REFERENCES locations(id),
    ghost_type  TEXT NOT NULL,
    witnesses   INTEGER NOT NULL,
    reported_at DATE NOT NULL
  );
`

const LOCATIONS = [
  ['Manila Film Center', 'Manila'],
  ['Balete Drive', 'Quezon City'],
  ['Diplomat Hotel', 'Baguio'],
  ['Clark Air Base', 'Angeles'],
  ['Manila Metropolitan Theater', 'Manila'],
  ['Teachers Camp', 'Baguio'],
  ['Laperal House', 'Baguio'],
  ['Fort Santiago', 'Manila'],
]
const GHOST_TYPES = ['apparition', 'white lady', 'poltergeist', 'orb', 'shadow']

// A tiny deterministic generator (a linear congruential generator). No
// randomness, so everyone's database is identical.
function makeRows(n) {
  let x = 20260826
  const next = () => (x = (x * 1103515245 + 12345) & 0x7fffffff)
  const rows = []
  for (let i = 0; i < n; i++) {
    const bits = () => (next() >>> 8) & 0xffff   // high bits: the low bits of an LCG barely change
    const location_id = 1 + (bits() % LOCATIONS.length)
    const ghost_type = GHOST_TYPES[bits() % GHOST_TYPES.length]
    const witnesses = bits() % 10
    const month = 1 + (bits() % 6)          // Jan-Jun 2026
    const day = 1 + (bits() % 28)
    const reported_at = `2026-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
    rows.push({ location_id, ghost_type, witnesses, reported_at })
  }
  return rows
}

const db = newDb()
db.public.none(SCHEMA)
for (const [name, city] of LOCATIONS) {
  db.public.none(`INSERT INTO locations (name, city) VALUES ('${name}', '${city}')`)
}
for (const r of makeRows(200)) {
  db.public.none(
    `INSERT INTO sightings (location_id, ghost_type, witnesses, reported_at) VALUES (${r.location_id}, '${r.ghost_type}', ${r.witnesses}, '${r.reported_at}')`
  )
}
const { Pool } = db.adapters.createPg()
export const pool = new Pool()
